USE meetsphere_db;

-- Run this once if your existing meeting_payments table was created by an older ZIP.
-- The latest backend also performs this migration automatically when an API request arrives.

SET @db = DATABASE();

SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='meeting_id')=0,
  'ALTER TABLE meeting_payments ADD COLUMN meeting_id INT NOT NULL DEFAULT 0', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='user_id')=0,
  'ALTER TABLE meeting_payments ADD COLUMN user_id INT NOT NULL DEFAULT 0', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='meeting_title')=0,
  'ALTER TABLE meeting_payments ADD COLUMN meeting_title VARCHAR(180) NOT NULL DEFAULT ''''', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='user_name')=0,
  'ALTER TABLE meeting_payments ADD COLUMN user_name VARCHAR(120) NOT NULL DEFAULT ''''', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='user_email')=0,
  'ALTER TABLE meeting_payments ADD COLUMN user_email VARCHAR(190) NOT NULL DEFAULT ''''', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='amount')=0,
  'ALTER TABLE meeting_payments ADD COLUMN amount DECIMAL(12,2) NOT NULL DEFAULT 0', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='method')=0,
  'ALTER TABLE meeting_payments ADD COLUMN method VARCHAR(40) NOT NULL DEFAULT ''Online Payment''', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='transaction_id')=0,
  'ALTER TABLE meeting_payments ADD COLUMN transaction_id VARCHAR(190) NOT NULL DEFAULT ''''', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='gateway_order_id')=0,
  'ALTER TABLE meeting_payments ADD COLUMN gateway_order_id VARCHAR(190) NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='gateway_payment_id')=0,
  'ALTER TABLE meeting_payments ADD COLUMN gateway_payment_id VARCHAR(190) NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='payment_status')=0,
  'ALTER TABLE meeting_payments ADD COLUMN payment_status VARCHAR(30) NOT NULL DEFAULT ''Created''', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='created_at')=0,
  'ALTER TABLE meeting_payments ADD COLUMN created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='meeting_payments' AND COLUMN_NAME='paid_at')=0,
  'ALTER TABLE meeting_payments ADD COLUMN paid_at DATETIME NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

SELECT id, user_id, user_name, user_email, meeting_title, amount, method, transaction_id, payment_status, paid_at, created_at
FROM meeting_payments ORDER BY created_at DESC;
